head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.vScrenID = 'ULDSTF26330.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + scwin.gDepCd;
    dts_emp.Reset();
};
scwin.fn_HeaderInit = function() {

    //dts_FileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_FileList.insertRow();
    //dts_tmpFile.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_tmpFile.insertRow();
};
scwin.fn_Init = function() {
    var ToDay = new Date();
    var yyyy = parseInt(ToDay.getYear(), 10);
    var str = "^--선택해주세요,";
    var str2 = "";
    for (var i = yyyy; i >= 2008; i--) {
        str += i + "^" + i + ",";
        str2 += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    str2 = str2.substring(0, str2.length - 1);
    cmb_ACNTCLS_YY.CBData = str;
};
scwin.fn_SelectAttach = function() {
    if (file.getValue() == "") return;
    txb_ATTACH_FILE_NM.setValue(file.getValue());
    dts_FileList.setCellData(1, "fileInfo", file.getValue());
    dts_FileList.setCellData(1, "fileUrl", file.getValue());
};
scwin.fn_checkDoubleInput = function() {
    var url = "/FncPrfmNewsData.do?method=countExistFncPrfmNewsData" + "&ACNTCLS_YY=" + $c.stf.getObjectValue(cmb_ACNTCLS_YY) + "&ACNTCLS_MM=" + $c.stf.getObjectValue(cmb_ACNTCLS_MM) + "&WRTRPT_KIND_CD=" + $c.stf.getObjectValue(cmb_WRTRPT_KIND_CD) + "&FS_WRT_METHD_CD=" + $c.stf.getObjectValue(cmb_FS_WRT_METHD_CD) + "&LD_MKT_TP_CD=" + $c.stf.getObjectValue(rdo_MKT_ID);
    dts_DoubleChk.DataID = encodeURI(url);
    dts_DoubleChk.Reset();
    return dts_DoubleChk.getCellData(1, "CNT");
};
scwin.fn_Save = function() {
    var file_nm = file.getValue();
    var suffix = file_nm.substring(file_nm.lastIndexOf(".") + 1);
    if ($c.stf.getObjectValue(cmb_ACNTCLS_YY) == '') {
        $c.win.alert("결산년도를 선택해주세요.");
        return;
    }
    if (suffix.indexOf('xls') == -1) {
        $c.win.alert("엑셀파일만 업로드 가능합니다.");
        return;
    }
    var chkMsg = '';
    if (scwin.fn_checkDoubleInput() > 0) {
        chkMsg = "기존 결산자료가 등록되어있습니다.\r\n" + "엑셀자료를 재 업로드 하시겠습니까?\r\n" + "\r\n" + "재업로드시에는 기존자료는 삭제됩니다.";
    } else {
        chkMsg = "엑셀자료를 업로드 하시겠습니까?";
    }
    if (window.confirm(chkMsg)) {
        LastJob = "저장";
        trs_Save.Action = "/FncPrfmNewsData.do?method=registerIfrsData" + "&ACNTCLS_YY=" + $c.stf.getObjectValue(cmb_ACNTCLS_YY) + "&ACNTCLS_MM=" + $c.stf.getObjectValue(cmb_ACNTCLS_MM) + "&WRTRPT_KIND_CD=" + $c.stf.getObjectValue(cmb_WRTRPT_KIND_CD) + "&FS_WRT_METHD_CD=" + $c.stf.getObjectValue(cmb_FS_WRT_METHD_CD) + "&LD_MKT_TP_CD=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&EMP_NO=" + js_emp_no + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pFile=dts_FileList)";
        trs_Save.post();
    }
};
scwin.doTemplateUpload = function() {
    var file_nm = upload_template.getValue();
    var suffix = file_nm.substring(file_nm.lastIndexOf(".") + 1);
    var wrtrptKindCd = $c.stf.getObjectText(cmb_WRTRPT_KIND_CD);
    var wrtrptKindTxt = wrtrptKindCd + '용 양식을 업로드하시겠습니까?(기존 양식은 없어짐)';
    if (!window.confirm(wrtrptKindTxt)) {
        return;
    }
    if (suffix.indexOf('xls') == -1) {
        $c.win.alert("엑셀파일만 업로드 가능합니다.");
        return;
    }
    var chkMsg = "업로드 하시겠습니까?";
    if (window.confirm(chkMsg)) {
        LastJob = "저장";
        tr_template.Action = "/FncPrfmNewsData.do?method=uploadFncTemplate" + "&ACNTCLS_YY=" + $c.stf.getObjectValue(cmb_ACNTCLS_YY) + "&ACNTCLS_MM=" + $c.stf.getObjectValue(cmb_ACNTCLS_MM) + "&WRTRPT_KIND_CD=" + $c.stf.getObjectValue(cmb_WRTRPT_KIND_CD) + "&FS_WRT_METHD_CD=" + $c.stf.getObjectValue(cmb_FS_WRT_METHD_CD) + "&LD_MKT_TP_CD=" + $c.stf.getObjectValue(rdo_MKT_ID);
        tr_template.KeyValue = "JSP(I:pFile=dts_tmpFile)";
        tr_template.Post();
    }
};
scwin.fn_gridInit = function(pLdMktTp) {
    var isView = true;
    if (pLdMktTp == '1') {
        isView = false;
    } else if (pLdMktTp == '2') {
        isView = true;
    }
    $c.cm.setColumnProp(grd_Grid, "HDCOM_YN", "Show", !isView);
    $c.cm.setColumnProp(grd_Grid, "SECT_TP_CD", "Show", isView);
    $c.cm.setColumnProp(grd_Grid, "KOSDAQ100_YN", "Show", isView);
    $c.cm.setColumnProp(grd_Grid, "STAR30_YN", "Show", isView);
    $c.cm.setColumnProp(grd_Grid, "PREMIER_YN", "Show", isView);

    // 유가,코스닥 모두 지수업종대분류명, 지수업종중분류명 표출
    //grd_Grid.ColumnProp("IDX_IND_UPCLSS_CD", "Show") = isView;
    //grd_Grid.ColumnProp("IDX_IND_MIDCLSS_CD", "Show") = isView;

};
scwin.fn_list_sync = function() {
    if ($c.stf.getObjectValue(cmb_ACNTCLS_YY) == '') {
        $c.win.alert("결산년도를 선택해주세요.");
        return;
    }
    scwin.fn_gridInit($c.stf.getObjectValue(rdo_MKT_ID));
    $c.cm.ShowWin(grd_Grid);
    var url = "/FncPrfmNewsData.do?method=listFncPrfmNewsData" + "&SEARCH_TYP=A1" + "&ACNTCLS_YY=" + $c.stf.getObjectValue(cmb_ACNTCLS_YY) + "&ACNTCLS_MM=" + $c.stf.getObjectValue(cmb_ACNTCLS_MM) + "&LD_MKT_TP_CD=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&WRTRPT_KIND_CD=" + $c.stf.getObjectValue(cmb_WRTRPT_KIND_CD) + "&FS_WRT_METHD_CD=" + $c.stf.getObjectValue(cmb_FS_WRT_METHD_CD) + "&CURR_UNIT=" + $c.stf.getObjectValue(cmb_CURR_UNIT) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};
scwin.makeExcelFile = function() {
    scwin.fn_gridInit($c.stf.getObjectValue(rdo_MKT_ID));
    var wrtrptKindCd = $c.stf.getObjectText(cmb_WRTRPT_KIND_CD);
    var wrtrptKindTxt = wrtrptKindCd + '용 보도자료를 만들겠습니까?(기존 파일에 덮어씀)';
    if (!window.confirm(wrtrptKindTxt)) {
        return;
    }
    $c.cm.ShowWin(grd_Grid);
    var url = "/FncPrfmNewsData.do?method=makeExcelData" + "&ACNTCLS_YY=" + $c.stf.getObjectValue(cmb_ACNTCLS_YY) + "&ACNTCLS_MM=" + $c.stf.getObjectValue(cmb_ACNTCLS_MM) + "&LD_MKT_TP_CD=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&WRTRPT_KIND_CD=" + $c.stf.getObjectValue(cmb_WRTRPT_KIND_CD) + "&FS_WRT_METHD_CD=" + $c.stf.getObjectValue(cmb_FS_WRT_METHD_CD) + "&CURR_UNIT=" + $c.stf.getObjectValue(cmb_CURR_UNIT) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_excel_result.DataID = encodeURI(url);
    dts_excel_result.Reset();
};
scwin.fn_NOTI_COM = function() {
    var gMsg = "" + "1. 재무제표별로 엑셀파일을 업로드합니다.( 확장자 : xls )\n" + "    ※ (엑셀업로드시에는 엑셀이 열려있거나 문서보안이 되어있으면 업로드가 되지 않으므로\n" + "    엑셀을 닫거나  문서보안을 해제한 후에 업로드합니다.)\n" + "\n" + "2. 엑셀에 결산실적대상법인은 종목코드 6자리에 A를 붙여 입력합니다.[A+종목코드]\n" + "\n" + "3. 엑셀에 재무계정값의 수치단위는 유가 [백만원], 코스닥 [원]단위로 입력합니다.\n" + "\n" + "4. 엑셀에서 재무계정값의 추출은 엑셀헤더의 계정명과 시스템 등록된  재무계정명이 일치했을때만\n" + "    추출되므로 엑셀헤더  재무계정명은 시스템에 등록된 계정명을 입력합니다.\n" + "\n" + "5. 당기3개월, 전기3개월 계정값이 없는 경우 1분기 및 결산때에는 항목값을 '0'으로 입력합니다.\n" + "\n" + "6. 지배 순이익 계정은 연결 재무제표시에만 사용하는 계정입니다.\n" + "\n" + "7. 시스템에 등록된 이외의 계정항목(지수업종, 소속부, 프리미어지수, 스타지수)의 값은\n" + "   시스템 값을 사용합니다.";
    txa_NOTI_COM.Text = gMsg;
};
