    var gMsg = "" + "종목코드\n" + "지주회사여부\n" + "자산총계_당기\n" + "자산총계_전기\n" + "부채총계_당기\n" + "부채총계_전기\n" + "자본총계_당기\n" + "자본총계_전기\n" + "자본금_당기\n" + "자본금_전기\n" + "매출액_전분기3개월\n" + "매출액_당기3개월\n" + "매출액_당기누적\n" + "매출액_전기3개월\n" + "매출액_전기누적\n" + "영업이익_전분기3개월\n" + "영업이익_당기3개월\n" + "영업이익_당기누적\n" + "영업이익_전기3개월\n" + "영업이익_전기누적\n" + "법인세전이익_전분기3개월\n" + "법인세전이익_당기3개월\n" + "법인세전이익_당기누적\n" + "법인세전이익_전기3개월\n" + "법인세전이익_전기누적\n" + "순이익_전분기3개월\n" + "순이익_당기3개월\n" + "순이익_당기누적\n" + "순이익_전기3개월\n" + "순이익_전기누적\n" + "지배순이익_전분기3개월\n" + "지배순이익_당기3개월\n" + "지배순이익_당기누적\n" + "지배순이익_전기3개월\n" + "지배순이익_전기누적\n";
    txa_NOTI_KOSPI.Text = gMsg;
};
scwin.fn_NOTI_KOSDAQ = function() {
    var gMsg = "" + "종목코드\n" + "자산총계_당기\n" + "자산총계_전기\n" + "부채총계_당기\n" + "부채총계_전기\n" + "자본총계_당기\n" + "자본총계_전기\n" + "자본금_당기\n" + "자본금_전기\n" + "매출액_전분기3개월\n" + "매출액_당기3개월\n" + "매출액_당기누적\n" + "매출액_전기3개월\n" + "매출액_전기누적\n" + "영업이익_전분기3개월\n" + "영업이익_당기3개월\n" + "영업이익_당기누적\n" + "영업이익_전기3개월\n" + "영업이익_전기누적\n" + "법인세전이익_전분기3개월\n" + "법인세전이익_당기3개월\n" + "법인세전이익_당기누적\n" + "법인세전이익_전기3개월\n" + "법인세전이익_전기누적\n" + "순이익_전분기3개월\n" + "순이익_당기3개월\n" + "순이익_당기누적\n" + "순이익_전기3개월\n" + "순이익_전기누적\n" + "지배순이익_전분기3개월\n" + "지배순이익_당기3개월\n" + "지배순이익_당기누적\n" + "지배순이익_전기3개월\n" + "지배순이익_전기누적\n";
    txa_NOTI_KOSDAQ.Text = gMsg;
};
scwin.showAlertMsg = function(msg) {
    if (msg.indexOf('50014') != -1) {
        $c.win.alert('첨부하려는 파일을 열어놓은 경우, 파일 첨부가 불가능 합니다.\r\n첨부하려는 파일을 닫고 다시 진행하시기 바랍니다.');
    } else if (msg.indexOf('50073') != -1) {
        //연결시간 초과 메세지 이지만 어떠한 에러 없이 DB insert 잘되고, 파일 잘 만들어 져서 그냥 정상 메세지 취급
        $c.win.alert('업로드가 완료되었습니다.');
    } else $c.win.alert(msg);
};
scwin.file_OnClick = function() {
    scwin.fn_SelectAttach();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Save();
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.MaxTab_01_OnSelChanged = function(nIndex) {
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        $c.stf.showObj(panel_Hidden, false);
        $c.stf.showObj(btn_Save, true);
        $c.stf.showObj(btn_Search, false);
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        $c.stf.showObj(panel_Hidden, true);
        $c.stf.showObj(btn_Save, false);
        $c.stf.showObj(btn_Search, true);
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        $c.stf.showObj(panel_Hidden, true);
        $c.stf.showObj(btn_Save, false);
        $c.stf.showObj(btn_Search, false);
    }
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.trs_Save_OnFail = function() {
    //alert_error(trs_Save);
    scwin.showAlertMsg(trs_Save.ErrorMsg);
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001", ""));
    dts_FileList.removeAll();
    scwin.fn_HeaderInit();
    $c.stf.setObjectValue(txb_ATTACH_FILE_NM, "");
    if ($c.stf.getObjectValue(cmb_FS_WRT_METHD_CD) == "1") {
        location.href = "/internal/stf/fnc/org_individual.xls";
    } else {
        location.href = "/internal/stf/fnc/org_connected.xls";
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_ABBRV.setValue("");
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_COM_SRCH_onclick = function() {
