scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    scwin.fn_NOTI_COM();
    scwin.fn_NOTI_KOSPI();
    scwin.fn_NOTI_KOSDAQ();
    MaxTab_01.setSelectedTabIndex(1);
    if (scwin.gLdMktTp == '1' || scwin.gLdMktTp == '2') {
        $c.stf.showObj(panel_mkt, false);
        $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
        $c.cm.setColumnProp(grd_Grid, "LD_MKT_TP_CD", "Show", false);
        scwin.fn_gridInit(scwin.gLdMktTp);
    }
    scwin.fn_Init();
    scwin.fn_HeaderInit();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_ABBRV);
};
