scwin.upload_template_OnClick = function() {
    if (upload_template.getValue() == "") return;
    txt_template.setValue(upload_template.getValue());
    dts_tmpFile.setCellData(1, "fileInfo", upload_template.getValue());
    dts_tmpFile.setCellData(1, "fileUrl", upload_template.getValue());
};
