    scwin.doTemplateUpload();
};
scwin.tr_template_OnSuccess = function() {
    $c.win.alert('엑셀 양식 업로드 완료');
    txt_template.setValue("");
    dts_tmpFile.removeAll();
    scwin.fn_HeaderInit();
};
scwin.tr_template_OnFail = function() {
    scwin.showAlertMsg(tr_template.ErrorMsg);
};
